-- Now that every existing course_id has a matching course, link the legacy
-- text columns to it. NOT VALID skips checking pre-existing rows so a stray
-- legacy id can't block the migration; new rows are checked.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'enrollments_course_id_fkey') then
    alter table public.enrollments add constraint enrollments_course_id_fkey
      foreign key (course_id) references public.courses (id) not valid;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'invite_codes_course_id_fkey') then
    alter table public.invite_codes add constraint invite_codes_course_id_fkey
      foreign key (course_id) references public.courses (id) not valid;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'announcements_course_id_fkey') then
    alter table public.announcements add constraint announcements_course_id_fkey
      foreign key (course_id) references public.courses (id) not valid;
  end if;
end $$;
